using namespace moon;void require(bool v){if(!v)throw std::runtime_error("symmetry regression");}
int main(){SymmetryAxes a;a.horizontal=true;auto p=symmetryPoints({1,0},6,4,a,defaultSymmetryCenter(6,4));require(p.size()==2&&p[1].x==1&&p[1].y==3);a={};a.vertical=true;p=symmetryPoints({1,0},6,4,a,defaultSymmetryCenter(6,4));require(p.size()==2&&p[1].x==4);a={};a.rotational=true;p=symmetryPoints({3,2},5,5,a,defaultSymmetryCenter(5,5));require(p.size()==4);require(symmetryAxisDragAllowed(true,false)==false);require(symmetryAxisDragAllowed(true,true));auto c=moveSymmetryCenter(defaultSymmetryCenter(6,4),SymmetryAxis::Horizontal,{0,1.26},6,4);require(c.y==1.5);a={};a.horizontal=true;a.vertical=true;p=symmetryPoints({2,2},5,5,a,defaultSymmetryCenter(5,5));require(p.size()==1);Document d(5,5);d.symmetryAxes=a;d.beginStroke({2,2},0x800000ff);d.commitStroke();require(d.pixels()[12]==0x800000ff&&d.historySize()==1);d.undo();require(d.pixels()[12]==0);d.beginStroke({0,0},0xff123456);d.cancelStroke();require(d.historySize()==1&&d.pixels()[0]==0);d.symmetryAxes={};d.symmetryAxes.vertical=true;d.beginStroke({0,0},0xff123456);d.commitStroke();require(d.pixels()[0]==d.pixels()[4]);d=Document(6,4);d.symmetryAxes.vertical=true;d.beginStroke({2,0},0xff000000);d.updateStroke({2,3});d.commitStroke();d.beginStroke({3,0},0xff000000);d.updateStroke({3,3});d.commitStroke();auto before=d.pixels();const auto h=d.historySize();d.fillPixels({0,0},0xff112233,{});require(d.pixels()[0]==0xff112233&&d.pixels()[5]==0xff112233&&d.historySize()==h+1);d.undo();require(d.pixels()==before);d.redo();require(d.pixels()[0]==0xff112233);ShapeSpec spec;spec.kind=ShapeKind::Rectangle;spec.start={0,0};spec.end={0,0};d.beginShapePreview();d.updateShapePreview(spec,0xff778899);d.cancelGradient();require(d.historySize()==h+1); }
